import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as t,o,af as i}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const k=JSON.parse('{"title":"Volcengine Ark tutorial","description":"Open the Ark console for an API Key, follow official docs for the first call, or install the official CLI. No invented base URL.","frontmatter":{"title":"Volcengine Ark tutorial","description":"Open the Ark console for an API Key, follow official docs for the first call, or install the official CLI. No invented base URL.","domain":"product","tags":["api"],"role":"tutorial"},"headers":[],"relativePath":"products/volcengine-ark/volcengine-ark.md","filePath":"products/volcengine-ark/volcengine-ark.md","lastUpdated":1787110548000}'),r={name:"products/volcengine-ark/volcengine-ark.md"};function n(l,e,s,d,c,h){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="volcengine-ark-tutorial" tabindex="-1">Volcengine Ark tutorial <a class="header-anchor" href="#volcengine-ark-tutorial" aria-label="Permalink to &quot;Volcengine Ark tutorial&quot;">​</a></h1><blockquote><p>Product page: <a href="https://www.volcengine.com/product/ark" target="_blank" rel="noreferrer">volcengine.com/product/ark</a>. First HTTP call: official <a href="https://www.volcengine.com/docs/82379/1399008" target="_blank" rel="noreferrer">quick start</a>. This page does not invent endpoints or model IDs.</p></blockquote><h2 id="goals-and-non-goals" tabindex="-1">Goals and non-goals <a class="header-anchor" href="#goals-and-non-goals" aria-label="Permalink to &quot;Goals and non-goals&quot;">​</a></h2><p><strong>Audience:</strong> frontend / Node engineers wiring Doubao models.</p><p><strong>You will:</strong> open the API Key page, know where the docs tree lives, and be able to install the official CLI.</p><p><strong>You will not:</strong> treat the Doubao app as the console, treat Trae as Ark, or paste a stale model table.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>A Volcengine account.</li><li>npm, if you want the CLI.</li></ul><h2 id="open-it-in-15-minutes" tabindex="-1">Open it in 15 minutes <a class="header-anchor" href="#open-it-in-15-minutes" aria-label="Permalink to &quot;Open it in 15 minutes&quot;">​</a></h2><h3 id="_1-get-an-api-key" tabindex="-1">1. Get an API Key <a class="header-anchor" href="#_1-get-an-api-key" aria-label="Permalink to &quot;1. Get an API Key&quot;">​</a></h3><p>Open <a href="https://ark.volcengine.com/region:cn-beijing/apiKey" target="_blank" rel="noreferrer">Get API KEY</a> (linked from the Volcengine homepage next to Ark).</p><p>Create-key clicks and project switching follow the official “get and configure API Key” doc. This page does not invent a SPA click path.</p><h3 id="_2-first-call-official-page" tabindex="-1">2. First call = official page <a class="header-anchor" href="#_2-first-call-official-page" aria-label="Permalink to &quot;2. First call = official page&quot;">​</a></h3><p>Open <a href="https://www.volcengine.com/docs/82379/1399008" target="_blank" rel="noreferrer">quick start</a> (updated 2026-01-30). Pick models from the official <strong>模型列表</strong> sidebar. Do not copy IDs from this site.</p> The no-JS scrape of quick start is empty. Do not fill `base_url` from a third-party blog. <h3 id="_3-optional-ark-cli" tabindex="-1">3. Optional: Ark CLI <a class="header-anchor" href="#_3-optional-ark-cli" aria-label="Permalink to &quot;3. Optional: Ark CLI&quot;">​</a></h3><p>Volcengine homepage, verbatim:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @volcengine/ark-cli@latest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span></span></code></pre></div><p>Product page: the official CLI does auth, model calls, and resource management; it supports Claude Code, Cursor, and TRAE.</p><p>Subcommands follow the official guide. This page does not invent flags.</p><h2 id="official-surface-docs-sidebar-2026-08-19" tabindex="-1">Official surface (docs sidebar, 2026-08-19) <a class="header-anchor" href="#official-surface-docs-sidebar-2026-08-19" aria-label="Permalink to &quot;Official surface (docs sidebar, 2026-08-19)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Group</th><th>Sidebar items</th><th>This site</th></tr></thead><tbody><tr><td>Start</td><td>Intro, quick start, model list, prices, Doubao 1.8</td><td>Links out</td></tr><tr><td>Invoke</td><td>Text, multimodal, image, video, domain, tools</td><td>Official pages</td></tr><tr><td>Advanced</td><td>Third-party tools, Responses API</td><td><a href="./volcengine-ark-cookbook.html">Cookbook</a></td></tr><tr><td>Deploy</td><td>Online / low-latency / unit / batch</td><td>Map row</td></tr><tr><td>Advanced capability</td><td>Fine-tune</td><td>Map row</td></tr><tr><td>Coding Plan</td><td>Overview, quick start, coding tools</td><td>Cookbook</td></tr></tbody></table><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="./volcengine-ark-cookbook.html">Cookbook</a></li><li><a href="./volcengine-ark-cheatsheet.html">Cheatsheet</a></li><li><a href="/tech/fundamentals/LLM.html">Learn LLM</a></li></ul>',24)])])}const m=a(r,[["render",n]]);export{k as __pageData,m as default};
